query GetApiUsageConnection ($page: ConnectionInput, $authType: String, $operationType: String, $timeRange: TimeRangeInput, $noCache: Boolean = false) {
  analytics {
    usage {
      api {
        apiUsageConnection(page: $page, authType: $authType, operationType: $operationType, timeRange: $timeRange, noCache: $noCache) {
          edges {
            cursor
            node {
              ... APIUsageRecordDefaultFields
            }
          }
          pageInfo {
            ... PageInfoDefaultFields
          }
          totalCount
          summaries {
            date
            authType
            totalRequests
            totalErrors
            avgDurationMs
            totalComplexity
            uniqueUsers
            uniqueTokens
          }
          operationSummaries {
            operationType
            totalRequests
            totalErrors
            uniqueOperations
            avgDurationMs
            totalComplexity
          }
        }
      }
    }
  }
}
fragment APIUsageRecordDefaultFields on APIUsageRecord {
  id
